{
  "definition_simple": "苦苦地等待；在艰苦或焦虑的心情中耐着性子长久等待。",
  "definition_standard": "动词。指怀着焦急、痛苦、坚忍或充满期盼的心情，在困境或漫长时间中苦苦等待结果、时机或特定对象的到来。",
  "pos": "动词",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "text": "老人每天坐在门前，苦待儿子的归来。"
    },
    {
      "tier": "T2",
      "text": "他在站台上苦待了整整一个晚上，列车却晚点了。"
    },
    {
      "tier": "T2",
      "text": "连续几个月没有下雨，村民们都在苦待甘霖。"
    },
    {
      "tier": "T3",
      "text": "被困在风雪中的登山队员，正苦待救援队的到来。"
    },
    {
      "tier": "T3",
      "text": "创业初期十分艰难，大家都在苦待第一个商业转机。"
    },
    {
      "tier": "T4",
      "text": "他苦待良机多年，终于在这次行业变革中脱颖而出。"
    },
    {
      "tier": "T4",
      "text": "面对市场行情的持续低迷，投资者只能苦待转机。"
    },
    {
      "tier": "T5",
      "text": "纵使前路渺茫、音讯全无，她依旧苦待故人，未曾动摇。"
    },
    {
      "tier": "T5",
      "text": "这支孤军在弹尽粮绝的绝境中苦待援兵，展现出惊人的毅力。"
    },
    {
      "tier": "T6",
      "text": "历经十载沉浮与落魄，他苦待昭雪，终在卷帙浩繁的历史公案中得还清白。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "酷待",
      "explanation": "读音与“苦待”仅第一字声调不同（去声 kù 对上声 kǔ），字面容易误听，但“酷待”意思是残酷虐待，语义截然相反。"
    },
    {
      "word": "苦态",
      "explanation": "读音与“苦待”仅第二字声母是否送气不同（t 对 d），发音部位相同极易混淆，但“苦态”是名词，指愁苦的神态。"
    },
    {
      "word": "姑待",
      "explanation": "读音与“苦待”仅第一字声母送气与声调不同（gū 对 kǔ），“姑待”为书面语指“姑且等待”，听觉与语境上极易相混。"
    }
  ],
  "primary_collocate": "良机",
  "collocation_distractors": [
    {
      "word": "效率",
      "explanation": "“效率”通常与“提高”、“讲求”搭配，不能作为耐苦等待的对象，语义搭配不通。"
    },
    {
      "word": "速度",
      "explanation": "虽然等待过程期盼加快，但现代汉语中不搭配“苦待速度”，应使用“加快速度”或“追求速度”。"
    },
    {
      "word": "方便",
      "explanation": "“方便”一般作为状语或与“提供”、“给予”搭配，不能作“苦待”的支配宾语。"
    }
  ],
  "collocation_wrong_collocate": "捷径",
  "cloze_distractors": [
    {
      "word": "亏待",
      "explanation": "词义完全不符，“亏待”指待遇不公或对不起人，无法代入等待救援队的语境中。"
    },
    {
      "word": "优待",
      "explanation": "词义与语境冲突，“优待”表示给予良好的待遇，不能用于表达在困境中焦急盼望的心情。"
    },
    {
      "word": "懒待",
      "explanation": "语体与含义不符，“懒待”为方言或口语词，表示“懒得去做”，不能表达长久的期盼和等待。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他在餐厅苦待了服务员十分钟，服务员才拿来菜单。",
      "explanation": "语境轻重失衡。“苦待”带有强烈的煎熬、痛苦与漫长感，用于日常餐厅等候点餐这类微不足道的小事属于语体严重错配。"
    },
    {
      "sentence": "老板每个月按时发足薪水，从来没有苦待过手下的员工。",
      "explanation": "混淆了“苦待”与“苛待/薄待”。现代汉语中“苦待”不表示在待遇上刻薄对待他人，此处应使用“苛待”或“亏待”。"
    },
    {
      "sentence": "这个实验需要把溶液苦待三十分钟后才能观察反应。",
      "explanation": "论元与主客体错配。“苦待”是有意识的主体在主观情绪上的耐熬与期盼，不能作为对客观实验物品施加的使动或静置动作。"
    }
  ],
  "spot_incorrect": {
    "sentence": "他在车站接朋友，仅仅苦待了五分钟便不耐烦地离开了。",
    "error_description": "“苦待”用于表达长久、艰辛的心情熬待，与“仅仅……五分钟便不耐烦”在时限与语义程度上产生明显矛盾。",
    "corrected": "他在车站接朋友，仅仅等待了五分钟便不耐烦地离开了。"
  },
